import sys


def main():
    data = sys.stdin.read().split()
    n, cap = int(data[0]), int(data[1])
    items = [(int(data[2 + 2 * i]), int(data[3 + 2 * i])) for i in range(n)]
    sys.setrecursionlimit(20000)

    def best(rem):
        if rem == 0:
            return 0
        result = -1
        for w, v in items:
            if w <= rem:
                sub = best(rem - w)
                if sub >= 0 and sub + v > result:
                    result = sub + v
        return result

    print(best(cap))


main()
